import { describe, expect, it } from "vitest";
import fixture from "./fixtures/host_statements.json";
import {
  checkDone,
  checkOffer,
  checkOpResult,
  parseDescriptor,
  pinIsConsistent,
  verifyStatement,
  type DelegationRequest,
} from "./hostStatements";

// Generated by the real host pipeline (Rust: relay -> passkey -> attest); see
// daemon_authz_tests.rs::regenerate_host_statement_fixture. The verifier under
// test is the production one used by the app.
const NOW = fixture.now;
const reply = (run: {
  challenge: string;
  options: unknown;
  offer: unknown;
}) => ({
  challenge: run.challenge,
  options: run.options as { publicKey: { challenge: string } },
  statement: run.offer,
});
const honest = reply(fixture.honest);
const request: DelegationRequest = {
  browserPub: fixture.request.browser_pub,
  kid: fixture.request.kid,
  dlg: fixture.request.dlg,
  caps: fixture.request.caps,
  nonce: fixture.request.nonce,
};

describe("host pinning", () => {
  it("derives the id from the key in the descriptor and rejects a mismatched pin", async () => {
    const host = await parseDescriptor(fixture.host.descriptor);
    expect(host.id).toBe(fixture.host.id);
    const other = await parseDescriptor(fixture.other_host.descriptor);
    expect(other.id).toBe(fixture.other_host.id);
    expect(await pinIsConsistent(host)).toBe(true);
    // Pinning another host's key under this host's id is detected.
    expect(await pinIsConsistent({ id: host.id, key: other.key })).toBe(false);
  });

  it.each([
    "",
    "chd1.",
    "chd1.short",
    "x".repeat(48),
    "chd1." + "!".repeat(43),
  ])("rejects the malformed descriptor %j", async (text) => {
    await expect(parseDescriptor(text)).rejects.toThrow();
  });
});

describe("real host statements", () => {
  it("accepts the host's real offer and completion for the request that was made", async () => {
    const host = await parseDescriptor(fixture.host.descriptor);
    const offer = await checkOffer(host, request, honest, NOW);
    expect(offer.notAfter - offer.issuedAt).toBe(86_400);
    const done = await checkDone(
      host,
      request,
      fixture.honest.challenge,
      offer,
      fixture.honest.done,
    );
    expect(done.notAfter).toBe(offer.notAfter);
  });

  it.each([
    ["key", fixture.swapped_pub],
    ["scope", fixture.swapped_caps],
    ["delegation id", fixture.swapped_dlg],
    ["nonce", fixture.swapped_nonce],
  ])(
    "rejects what the host signed for a relay-substituted %s",
    async (_name, swapped) => {
      const host = await parseDescriptor(fixture.host.descriptor);
      await expect(
        checkOffer(host, request, reply(swapped), NOW),
      ).rejects.toThrow(/does not match what was requested/);
    },
  );

  it("rejects an offer carrying the real challenge but swapped WebAuthn options or ceremony", async () => {
    const host = await parseDescriptor(fixture.host.descriptor);
    const options = structuredClone(honest.options);
    options.publicKey.challenge = "AAAA";
    await expect(
      checkOffer(host, request, { ...honest, options }, NOW),
    ).rejects.toThrow();
    await expect(
      checkOffer(host, request, { ...honest, challenge: "e".repeat(32) }, NOW),
    ).rejects.toThrow();
  });

  it("rejects an expiry the host did not sign, a stale reply and another host's signature", async () => {
    const host = await parseDescriptor(fixture.host.descriptor);
    await expect(
      checkOffer(
        host,
        request,
        { ...honest, statement: fixture.bad_expiry },
        NOW,
      ),
    ).rejects.toThrow();
    // An honest reply replayed long after it was issued.
    await expect(
      checkOffer(host, request, honest, NOW + 3600),
    ).rejects.toThrow();
    for (const statement of [
      fixture.other_signs_honest_payload,
      fixture.other_own_offer,
    ]) {
      await expect(
        checkOffer(host, request, { ...honest, statement }, NOW),
      ).rejects.toThrow();
    }
  });

  it("rejects a completion bound to another request, or one tampered in transit", async () => {
    const host = await parseDescriptor(fixture.host.descriptor);
    const offer = await checkOffer(host, request, honest, NOW);
    await expect(
      checkDone(
        host,
        { ...request, nonce: "f".repeat(32) },
        fixture.honest.challenge,
        offer,
        fixture.honest.done,
      ),
    ).rejects.toThrow();
    await expect(
      checkDone(host, request, fixture.honest.challenge, offer, {
        ...fixture.honest.done,
        p: fixture.honest.done.p.slice(0, -2) + "AA",
      }),
    ).rejects.toThrow();
    await expect(
      verifyStatement(host, { ...fixture.honest.done, extra: 1 }),
    ).rejects.toThrow();
  });

  it("binds every operation outcome, including failures, to the exact operation bytes", async () => {
    const host = await parseDescriptor(fixture.host.descriptor);
    const sent = { kid: fixture.op.kid, payloadB64u: fixture.op.payload };
    for (const status of [
      "executed",
      "replayed",
      "failed",
      "uncertain",
      "refused",
    ] as const) {
      const outcome = await checkOpResult(host, sent, fixture.op[status]);
      expect(outcome.status).toBe(status);
    }
    // An old success replayed as the answer to a different operation.
    await expect(
      checkOpResult(
        host,
        { kid: fixture.op.kid, payloadB64u: fixture.op.other_payload },
        fixture.op.executed,
      ),
    ).rejects.toThrow();
    await expect(
      checkOpResult(host, sent, fixture.op.executed_for_other_op),
    ).rejects.toThrow();
    await expect(
      checkOpResult(host, { ...sent, kid: "other" }, fixture.op.executed),
    ).rejects.toThrow();
  });
});
